// @ts-ignore generated by `opennextjs-cloudflare build`
import generatedWorker from "./.open-next/worker.js";
import { runWithRequestPathname } from "./lib/cloudflare/request-scope";
import {
  HTML_LANG,
  LOCALE_COOKIE,
  LOCALE_PREFIXES,
  matchLocale,
  type Locale,
} from "./lib/i18n/config";

interface GeneratedWorker {
  fetch(request: Request, env: unknown, ctx: unknown): Promise<Response>;
}

interface AssetBinding {
  fetch(request: Request | string): Promise<Response>;
}

const worker = generatedWorker as GeneratedWorker;

const securityHeaders = {
  "X-Content-Type-Options": "nosniff",
  "Referrer-Policy": "strict-origin-when-cross-origin",
  "Permissions-Policy": "camera=(), geolocation=(), microphone=()",
  "X-Frame-Options": "SAMEORIGIN",
};

const rscVary =
  "RSC, Next-Router-State-Tree, Next-Router-Prefetch, Next-Router-Segment-Prefetch, Next-Url";

function requestLocale(request: Request, pathname: string): {
  locale: Locale;
  explicit: boolean;
  routePath: string;
} {
  const segments = pathname.split("/");
  const prefix = LOCALE_PREFIXES[segments[1]?.toLowerCase() ?? ""];
  if (prefix) {
    return {
      locale: prefix,
      explicit: true,
      routePath: "/" + segments.slice(2).join("/"),
    };
  }

  const cookie = request.headers
    .get("cookie")
    ?.split(";")
    .map((part) => part.trim())
    .find((part) => part.startsWith(`${LOCALE_COOKIE}=`))
    ?.slice(LOCALE_COOKIE.length + 1);
  return {
    locale:
      cookie === "zh-CN" || cookie === "en"
        ? cookie
        : matchLocale(request.headers.get("accept-language")),
    explicit: false,
    routePath: pathname,
  };
}

function localeCookie(locale: Locale): string {
  return `${LOCALE_COOKIE}=${locale}; Path=/; Max-Age=31536000; SameSite=Lax`;
}

function redirectToChinese(request: Request, pathname: string): Response {
  const url = new URL(request.url);
  url.pathname = pathname === "/" ? "/zh" : `/zh${pathname}`;
  return new Response(null, {
    status: 307,
    headers: {
      ...securityHeaders,
      Location: url.toString(),
      "Set-Cookie": localeCookie("zh-CN"),
      "Cache-Control": "private, no-cache",
    },
  });
}

function legacyRedirect(request: Request): Response | null {
  const url = new URL(request.url);
  const segments = url.pathname.split("/");
  const prefix = LOCALE_PREFIXES[segments[1]?.toLowerCase() ?? ""];
  const routePath = prefix ? "/" + segments.slice(2).join("/") : url.pathname;
  if (routePath !== "/explore/browse") return null;

  url.pathname = `${prefix === "zh-CN" ? "/zh" : ""}/explore`;
  const headers = new Headers(securityHeaders);
  headers.set("Location", url.toString());
  headers.set("Cache-Control", "private, no-cache");
  return new Response(null, { status: 308, headers });
}

async function localImage(request: Request, assets: AssetBinding): Promise<Response | null> {
  if (request.method !== "GET" && request.method !== "HEAD") return null;
  const url = new URL(request.url);
  if (!/^\/(?:(?:en|zh(?:\-cn|\-hans)?)\/)?_next\/image$/.test(url.pathname)) {
    return null;
  }
  const source = url.searchParams.get("url");
  if (!source || !source.startsWith("/") || source.startsWith("//")) return null;

  const asset = await assets.fetch(
    new Request(new URL(source, url.origin), { method: request.method }),
  );
  if (!asset.ok) {
    return new Response(request.method === "HEAD" ? null : "Image not found", {
      status: 404,
      headers: { ...securityHeaders, "Cache-Control": "private, no-cache" },
    });
  }
  const headers = new Headers(securityHeaders);
  headers.set("Content-Type", asset.headers.get("Content-Type") ?? "application/octet-stream");
  headers.set("Cache-Control", "public, max-age=604800");
  headers.set("X-Luc-Static", "image");
  return new Response(request.method === "HEAD" ? null : asset.body, {
    status: 200,
    headers,
  });
}

async function staticPage(request: Request, assets: AssetBinding | undefined): Promise<Response | null> {
  if (!assets) return null;
  if (request.method !== "GET" && request.method !== "HEAD") return null;
  const url = new URL(request.url);
  const resolved = requestLocale(request, url.pathname);
  if (!resolved.explicit && resolved.locale === "zh-CN") {
    return redirectToChinese(request, url.pathname);
  }
  if (resolved.locale === "en" && url.pathname.startsWith("/en/")) return null;

  const normalizedPath =
    resolved.routePath === "/" ? "index" : resolved.routePath.replace(/^\/+|\/+$/g, "");
  const isRsc = request.headers.get("rsc") === "1" || url.searchParams.has("_rsc");
  const extension = isRsc ? "rsc" : "html";
  const localeDir = resolved.locale === "zh-CN" ? "zh/" : "";
  const assetUrl = new URL(
    `http://assets.local/luc-static/${localeDir}${normalizedPath}.${extension}`,
  );
  const asset = await assets.fetch(new Request(assetUrl, { method: request.method }));
  if (!asset.ok) return null;

  const headers = new Headers(securityHeaders);
  headers.set("Content-Type", isRsc ? "text/x-component" : "text/html; charset=utf-8");
  headers.set("Content-Language", HTML_LANG[resolved.locale]);
  headers.set("Set-Cookie", localeCookie(resolved.locale));
  headers.set("Cache-Control", "private, no-cache");
  headers.set("X-Luc-Static", extension);
  if (isRsc) headers.set("Vary", rscVary);

  return new Response(request.method === "HEAD" ? null : asset.body, {
    status: 200,
    headers,
  });
}

/**
 * Keep the original request path available to the read-only cache override.
 * Without this scope, Next sees only the rewritten English path and either
 * serves English HTML under `/zh` or has to render Chinese on every request.
 */
const customWorker = {
  async fetch(request: Request, env: unknown, ctx: unknown) {
    const assets = (env as { ASSETS?: AssetBinding }).ASSETS;
    const legacy = legacyRedirect(request);
    if (legacy) return legacy;

    if (assets) {
      const image = await localImage(request, assets);
      if (image) return image;
    }

    /*
     * Next's image endpoint is a root `/_next/image` route. A locale-aware
     * browser can still emit `/zh/_next/image` for an image discovered during
     * hydration; strip the locale prefix before the framework sees it.
     */
    const localizedInternalAsset = new URL(request.url);
    if (/^\/(?:en|zh(?:\-cn|\-hans)?)\/_next\//i.test(localizedInternalAsset.pathname)) {
      localizedInternalAsset.pathname = localizedInternalAsset.pathname.replace(
        /^\/(?:en|zh(?:\-cn|\-hans)?)(\/_next\/)/i,
        "$1",
      );
      request = new Request(localizedInternalAsset, request);
    }

    const staticResponse = await staticPage(request, assets);
    if (staticResponse) return staticResponse;

    const requestId = crypto.randomUUID();
    const requestMetadata = request as Request & {
      cf?: Record<string, unknown>;
    };
    const cf = {
      ...requestMetadata.cf,
      lucRequestId: requestId,
    };
    const scopedRequest = new Request(request, { cf } as RequestInit);
    return runWithRequestPathname(requestId, new URL(request.url).pathname, () =>
      worker.fetch(scopedRequest, env, ctx),
    );
  },
};

export default customWorker;
